# ============================================================================# WorksFree Build Package Integrity Verification Script# ============================================================================# Verifies that all app build artifacts include required files# ============================================================================param(    [string]$BuildRoot = "D:\release\candidates",    [string[]]$Apps = @("bom_exporter", "dwg_classifier", "dwg_batch_print", "korean_filename_normalizer", "conversion_verifier"))$ErrorCount = 0$WarningCount = 0Write-Host "`n========================================" -ForegroundColor CyanWrite-Host "WorksFree Build Integrity Verification" -ForegroundColor CyanWrite-Host "========================================`n" -ForegroundColor Cyanfunction Test-FileExists {    param(        [string]$Path,        [string]$Description,        [bool]$Critical = $true    )        if (Test-Path $Path) {        Write-Host "  OK $Description" -ForegroundColor Green        return $true    } else {        if ($Critical) {            Write-Host "  ERROR $Description - Missing!" -ForegroundColor Red            $script:ErrorCount++        } else {            Write-Host "  WARN $Description - Missing (optional)" -ForegroundColor Yellow            $script:WarningCount++        }        return $false    }}foreach ($app in $Apps) {    Write-Host "`n[$app]" -ForegroundColor Yellow    Write-Host "----------------------------------------" -ForegroundColor Gray        $appFolders = Get-ChildItem -Path $BuildRoot -Directory -Filter "${app}_v*" -ErrorAction SilentlyContinue | Sort-Object Name -Descending        if ($appFolders.Count -eq 0) {        Write-Host "  ERROR Build folder not found: $BuildRoot\${app}_v*" -ForegroundColor Red        $ErrorCount++        continue    }        $latestFolder = $appFolders[0]    Write-Host "Target: $($latestFolder.Name)" -ForegroundColor Gray        $portableFolder = Get-ChildItem -Path $latestFolder.FullName -Directory -Filter "*_portable" -ErrorAction SilentlyContinue | Select-Object -First 1        if (-not $portableFolder) {        Write-Host "  ERROR portable folder not found" -ForegroundColor Red        $ErrorCount++        continue    }        $portablePath = $portableFolder.FullName        # 1. EXE file    Test-FileExists -Path (Join-Path $portablePath "$app.exe") -Description "$app.exe" | Out-Null        # 2. _internal folder    $internalPath = Join-Path $portablePath "_internal"    Test-FileExists -Path $internalPath -Description "_internal folder" | Out-Null        if (Test-Path $internalPath) {        # 3. .wf_rpa folder        $wfRpaPath = Join-Path $internalPath ".wf_rpa"        Test-FileExists -Path $wfRpaPath -Description ".wf_rpa folder" | Out-Null                if (Test-Path $wfRpaPath) {            # 4. wf_rpa_config.json            Test-FileExists -Path (Join-Path $wfRpaPath "wf_rpa_config.json") -Description "wf_rpa_config.json" | Out-Null                        # 5. Google credentials            $credFiles = Get-ChildItem -Path $wfRpaPath -Filter ".silver-argon*.json" -ErrorAction SilentlyContinue            if ($credFiles.Count -gt 0) {                Write-Host "  OK Google credentials ($($credFiles.Count) files)" -ForegroundColor Green            } else {                Write-Host "  WARN Google credentials - Missing" -ForegroundColor Yellow                $WarningCount++            }                        # 6. App config folder            $appConfigPath = Join-Path $wfRpaPath $app            Test-FileExists -Path $appConfigPath -Description "App config folder (.wf_rpa\$app)" | Out-Null                        if (Test-Path $appConfigPath) {                # 7. settings.json (Required)                Test-FileExists -Path (Join-Path $appConfigPath "settings.json") -Description "settings.json" | Out-Null                                # 8. app_config.json (Required for shortcut name)                $appConfigJson = Join-Path $appConfigPath "app_config.json"                if (Test-FileExists -Path $appConfigJson -Description "app_config.json (for shortcut)" -Critical $true) {                    try {                        $config = Get-Content $appConfigJson -Raw -Encoding UTF8 | ConvertFrom-Json                        if ($config.identity.display_name) {                            Write-Host "    -> display_name: $($config.identity.display_name)" -ForegroundColor Cyan                        } else {                            Write-Host "    -> ERROR display_name field missing!" -ForegroundColor Red                            $ErrorCount++                        }                        if ($config.app_config.full_version) {                            Write-Host "    -> version: $($config.app_config.full_version)" -ForegroundColor Cyan                        }                    } catch {                        Write-Host "    -> ERROR JSON parsing failed: $_" -ForegroundColor Red                        $ErrorCount++                    }                }            }        }    }        # 9. create_desktop_shortcut.bat (Required)    Test-FileExists -Path (Join-Path $portablePath "create_desktop_shortcut.bat") -Description "create_desktop_shortcut.bat" | Out-Null        # 10. ZIP file (Optional - build mode 2 only)    $zipFile = Get-ChildItem -Path $latestFolder.FullName -Filter "*.zip" -ErrorAction SilentlyContinue | Select-Object -First 1    if ($zipFile) {        Write-Host "  OK ZIP file ($($zipFile.Name))" -ForegroundColor Green    } else {        Write-Host "  WARN ZIP file - Not found (build mode 1?)" -ForegroundColor Yellow        $WarningCount++    }}# SummaryWrite-Host "`n========================================" -ForegroundColor CyanWrite-Host "Verification Complete" -ForegroundColor CyanWrite-Host "========================================" -ForegroundColor Cyanif ($ErrorCount -eq 0 -and $WarningCount -eq 0) {    Write-Host "All checks passed!" -ForegroundColor Green    exit 0} elseif ($ErrorCount -eq 0) {    Write-Host "Warnings: $WarningCount (not critical)" -ForegroundColor Yellow    exit 0} else {    Write-Host "Errors: $ErrorCount, Warnings: $WarningCount" -ForegroundColor Red    Write-Host "`nMissing required files may cause app malfunction." -ForegroundColor Red    exit 1}